"""Generate src/audio/mp3_tables.rs from minimp3.h (CC0-1.0). Run once offline; prints sha256 of the input."""
import hashlib
import re
import sys

src_path, out_path = sys.argv[1], sys.argv[2]
raw = open(src_path, 'rb').read()
text = raw.decode('utf-8')


def array(name):
    m = re.search(r'static const [a-z0-9_]+ ' + re.escape(name) + r'\[[^\]]*\]\s*=\s*\{(.*?)\};', text, re.S)
    if not m:
        raise SystemExit('missing ' + name)
    body = re.sub(r'/\*.*?\*/', '', m.group(1), flags=re.S)
    return [v.strip() for v in body.replace('\n', ' ').split(',') if v.strip()]


def wrap(values, per=16):
    lines = []
    for i in range(0, len(values), per):
        lines.append('    ' + ', '.join(values[i:i + per]) + ',')
    return '\n'.join(lines)


tabs = array('tabs')
tab32 = array('tab32')
tab33 = array('tab33')
tabindex = array('tabindex')
linbits = array('g_linbits')
pow43 = [v.rstrip('f') for v in array('g_pow43')]
pow43 = [v if ('.' in v or 'e' in v) else v + '.0' for v in pow43]

dq = []
for x in [3, 7, 15, 31, 63, 127, 255, 511, 1023, 2047, 4095, 8191, 16383, 32767, 65535, 3, 5, 9]:
    for c in ['9.53674316e-07', '7.56931807e-07', '6.00777173e-07']:
        dq.append(f'{c}f32 / {x}.0')

out = []
out.append('// Generated by gen_mp3_tables.py from minimp3.h (https://github.com/lieff/minimp3, CC0-1.0),')
out.append('// input sha256 ' + hashlib.sha256(raw).hexdigest() + '. Do not edit by hand.')
out.append('// Included by mp3.rs (include!), not a module.')
out.append('#[rustfmt::skip]')
out.append(f'const TABS: [i16; {len(tabs)}] = [\n{wrap(tabs)}\n];')
out.append('#[rustfmt::skip]')
out.append(f'const TAB32: [u8; {len(tab32)}] = [\n{wrap(tab32)}\n];')
out.append('#[rustfmt::skip]')
out.append(f'const TAB33: [u8; {len(tab33)}] = [\n{wrap(tab33)}\n];')
out.append('#[rustfmt::skip]')
out.append(f'const TABINDEX: [i16; {len(tabindex)}] = [\n{wrap(tabindex)}\n];')
out.append('#[rustfmt::skip]')
out.append(f'const LINBITS: [u8; {len(linbits)}] = [\n{wrap(linbits)}\n];')
out.append('#[rustfmt::skip]')
out.append('#[allow(clippy::excessive_precision)]')
out.append(f'const POW43: [f32; {len(pow43)}] = [\n{wrap(pow43, 8)}\n];')
out.append('#[rustfmt::skip]')
out.append('#[allow(clippy::excessive_precision)]')
out.append(f'const DEQ_L12: [f32; {len(dq)}] = [\n{wrap(dq, 3)}\n];')
open(out_path, 'w', encoding='utf-8', newline='\n').write('\n'.join(out) + '\n')
print('tabs', len(tabs), 'tab32', len(tab32), 'tab33', len(tab33), 'tabindex', len(tabindex), 'linbits', len(linbits), 'pow43', len(pow43), 'dq', len(dq))
